70	    unsafe fn unregister(adrv: &Opaque<Self::DriverType>) {
71	        // SAFETY: `adrv` is guaranteed to be a valid `DriverType`.
72	        unsafe { bindings::auxiliary_driver_unregister(adrv.get()) }
73	    }
